// WebMCP (https://webmachinelearning.github.io/webmcp/): the docs as tools for the agents of the browser,
// built on llms.txt and the .md version of the pages generated by vitepress-plugin-llms
interface ModelContextTool {
  name: string
  title?: string
  description: string
  inputSchema?: object
  annotations?: { readOnlyHint?: boolean }
  execute: (input: Record<string, unknown>) => Promise<unknown>
}

interface ModelContext {
  registerTool: (tool: ModelContextTool) => Promise<void>
}

async function fetchText(path: string): Promise<string> {
  const response = await fetch(path)

  if (!response.ok) {
    throw new Error(`${path}: ${response.status} ${response.statusText}`)
  }

  return response.text()
}

// /guide/bump -> /guide/bump.md, /commitlint/ -> /commitlint.md
function getMarkdownPath(path: string): string {
  const pathname = new URL(path, globalThis.location.origin).pathname.replace(/(?:\.html|\.md)?\/?$/, '')

  return pathname === ''
    ? '/llms.txt'
    : `${pathname}.md`
}

const tools: ModelContextTool[] = [
  {
    name: 'list_docs',
    title: 'List the docs of Relizy',
    description: 'Index of the documentation pages of Relizy (guides, configuration, CLI, commit linting, API), with their path and description, in markdown.',
    inputSchema: { type: 'object', properties: {} },
    annotations: { readOnlyHint: true },
    execute: () => fetchText('/llms.txt'),
  },
  {
    name: 'search_docs',
    title: 'Search the docs of Relizy',
    description: 'Find the documentation pages of Relizy whose title or description contains all the words of the query. Returns the matching lines of the index, with the path of each page.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Words to look for, e.g. "version groups" or "github release"' },
      },
      required: ['query'],
    },
    annotations: { readOnlyHint: true },
    execute: async ({ query }) => {
      const words = String(query).toLowerCase().split(/\s+/).filter(Boolean)
      const lines = (await fetchText('/llms.txt')).split('\n').filter(line => line.startsWith('- ['))
      const matches = lines.filter(line => words.every(word => line.toLowerCase().includes(word)))

      return matches.length > 0
        ? matches.join('\n')
        : `No page matches "${query}". Use list_docs to see all the pages.`
    },
  },
  {
    name: 'get_doc',
    title: 'Read a page of the docs of Relizy',
    description: 'Content of a documentation page of Relizy in markdown, from its path (e.g. "/guide/version-modes" or "/config/monorepo"). Defaults to the current page.',
    inputSchema: {
      type: 'object',
      properties: {
        path: { type: 'string', description: 'Path of the page, as given by list_docs or search_docs' },
      },
    },
    annotations: { readOnlyHint: true },
    execute: ({ path }) => fetchText(getMarkdownPath(typeof path === 'string' && path
      ? path
      : globalThis.location.pathname)),
  },
]

export function registerWebMcpTools() {
  const modelContext = (document as Document & { modelContext?: ModelContext }).modelContext

  if (!modelContext) {
    return
  }

  for (const tool of tools) {
    modelContext.registerTool(tool).catch(error => console.warn(`[webmcp] ${tool.name}:`, error))
  }
}
